      SUBROUTINE POSTERCC     PRINTS ELEMENTS AND MATRICES DURING CALCULATIONCC ----------------------------------------------------------------------      INCLUDE 'TRNSPRT_PARAM.CIN'      INCLUDE 'BROAD.CIN'      INCLUDE 'CONSTS.CIN'      INCLUDE 'DATA0A.CIN'      INCLUDE 'DATA0B.CIN'      INCLUDE 'DATA1A.CIN'      INCLUDE 'DATA1C.CIN'      INCLUDE 'DATA2A.CIN'      INCLUDE 'DATA2B.CIN'      INCLUDE 'DATA2D.CIN'      INCLUDE 'DBEND.CIN'      INCLUDE 'DRBND.CIN'      INCLUDE 'DSPEC.CIN'      INCLUDE 'ELM0A.CIN'      INCLUDE 'ELM0B.CIN'      INCLUDE 'ELM0C.CIN'      INCLUDE 'ELM0D.CIN'           INCLUDE 'ELM1A.CIN'      INCLUDE 'ELM2A.CIN'      INCLUDE 'ELM2B.CIN'      INCLUDE 'ELM2C.CIN'      INCLUDE 'ELM4A.CIN'      INCLUDE 'ELM4C.CIN'      INCLUDE 'ELM4D.CIN'      INCLUDE 'ELM5A.CIN'      INCLUDE 'ELM6.CIN'      INCLUDE 'ELM7B.CIN'      INCLUDE 'ELM8A.CIN'      INCLUDE 'ELM8B.CIN'      INCLUDE 'ELM8G.CIN'      INCLUDE 'ELM10A.CIN'      INCLUDE 'ELM10B.CIN'      INCLUDE 'ELM10C.CIN'      INCLUDE 'ELM11.CIN'      INCLUDE 'ELM13B.CIN'      INCLUDE 'ELM13C.CIN'      INCLUDE 'ELM14A.CIN'      INCLUDE 'ELM15A.CIN'      INCLUDE 'ELM13A.CIN'      INCLUDE 'ELM15B.CIN'      INCLUDE 'ELM15C.CIN'      INCLUDE 'ELM16A.CIN'      INCLUDE 'ELM16B.CIN'      INCLUDE 'ELM17A.CIN'      INCLUDE 'ELM19.CIN'      INCLUDE 'ELM26A.CIN'      INCLUDE 'ELM26B.CIN'      INCLUDE 'ELM28.CIN'      INCLUDE 'ELM38A.CIN'      INCLUDE 'ELM38B.CIN'      INCLUDE 'ELM41.CIN'      INCLUDE 'ETACOM.CIN'      INCLUDE 'INDBND.CIN'      INCLUDE 'INDPAR.CIN'      INCLUDE 'IOUNIT.CIN'      INCLUDE 'ISEEDX.CIN'      INCLUDE 'KELEM.CIN'      INCLUDE 'R.CIN'      INCLUDE 'RDCHAR.CIN'      INCLUDE 'STEPT1.CIN'CC     LOCAL VARIABLESC      CHARACTER*4     LABUPD      CHARACTER*7     CSD      CHARACTER*8     PNAME, HPLOT(8)      CHARACTER*9     CACOC      CHARACTER*10    SLANG, LABOUT, LABMIS      CHARACTER*11    CWORK1      CHARACTER*12    CCOC, CCOC2      CHARACTER*14    CDE0      CHARACTER*16    NUMREP      CHARACTER*20    CMIS      INTEGER         IDATA      INTEGER         TYPEN      LOGICAL         DOVC, VARIED      REAL            LOUT, K1NORM, K2OUT, K3OUT      REAL            CODO(6), VMO(6)      EQUIVALENCE     (PAR16,IPAR16)C ---------------------------------------------------------------------C      IF (TYPE .LE. 0) GO TO 5000      NBE = .FALSE.      IF (.NOT. MPRN) GO TO 5000      NBE = .TRUE.      NRT = .TRUE.      SONLY = .FALSE.      IF (.NOT. (PRON .AND. ELPR) .AND. TYPE .NE. 13) GO TO 70      LABOUT(1:8) = LABEL(NUM)(1:8)CC     DO VARY CODESC   30 DOVC = .TRUE.      DOVC = DOVC .AND. .NOT. (TYPEC .EQ. 8 .AND. RORC .GE. 3)      IF (.NOT. DOVC) GO TO 60       IVA = 0      KV = NIV(TYPE)      IF (KV .GT. 0) THEN        KV = MAX0(KV,NPARMS)        IF (TYPE .EQ. 14) KV = MIN0(KV,6)        DO 50 JV = 1, KV        K = I + IPTOJ(JV)        ISIG = TIE(K)        IF (ISIG .GE. 99) ISIG = 0        IVARY = IABS(ISIG)        IF (IVARY .NE. 0) THEN          IVARY = VSTOR(IVARY)          IVA = 1        ENDIF   50   CONTINUE      ENDIFC   60 IF (ONLY) THEN        IF (IVA .EQ. 0 .AND. TYPE .NE. 10 .AND. TYPE .NE. 13     1      .AND. TYPE .NE. 22 .AND. TYPE .NE. 23) GO TO 5000      ENDIF   70 GO TO ( 100, 200, 300, 400, 500, 600, 700, 800,5000,1000,     1       1100,1200,1300,1400,5000,1600,1700,1800,1900,2000,     2       2100,5000,5000,5000,2500,5000,2700,2800,2800,5000,     3       3100,5000,3300,3400,3500,3600,3700,3800,5000,5000,     4       4100,4200,4300,5000,4500,4600,4700,4800), TYPECC     1. -- BEAMC  100 NRT = .FALSE.      WORK1 = RI / UNITO(11)      IF (RMSADD) GO TO 130      IF (NEXT .EQ. 12) NBE = .FALSE.      IF ((ACCEL .OR. LTWISS) .AND. NEXT .EQ. 7) NBE = .FALSE.      IF (PRON .AND. ELPR)      1    WRITE (NOUT,9010) NUM, LABOUT, WORK1, XDIME(11)      GO TO 5000C  130 IF (PRON .AND. ELPR) THEN        IF (.NOT. SUPP) THEN          WRITE (NOUT,9011) NUM, LABOUT, WORK1, XDIME(11)        ELSE          WRITE (NOUT,9011) NUM, LABOUT        ENDIF      ENDIF      GO TO 5000CC     2. -- POLE FACE ROTATIONC  200 IF (.NOT. (PRON .AND. ELPR)) GO TO 5000      IF (TYPEC .EQ. 8) GO TO 270      IF (SUPP) GO TO 240      IF (PRAN2(3) .NE. 0.0 .OR. IPTOJ(3) .NE. 0) THEN        WRITE (NOUT,9021) LAYK, LAYL, LAYX      ENDIF      BEO = BE/UNITO(7)      HGAP = APB(2)/UNITO(1)      IF (NORD1 .GE. 2) THEN        IF (RABT .NE. 0.0 .OR. IPTOJ(4) .NE. 0) GO TO 220      ENDIF      IF (HGAP .EQ. 0.0 .AND. IPTOJ(2) .EQ. 0) THEN        WRITE (NOUT,9020) NUM, LABOUT, BEO, XDIME(7)      ELSE        WRITE (NOUT,9020) NUM, LABOUT, BEO, XDIME(7),     1                    HGAP, XDIME(1)      ENDIF      GO TO 5000C  220 RABO = RABT*UNITO(8)      IF (HGAP .EQ. 0.0 .AND. IPTOJ(2) .EQ. 0) THEN        WRITE (NOUT,9020) NUM, LABOUT, BEO, XDIME(7),     1                    RABO, XDIME(8)      ELSE        WRITE (NOUT,9020) NUM, LABOUT, BEO, XDIME(7),     1                    HGAP, XDIME(1), RABO, XDIME(8)      ENDIF      GO TO 5000C  240 WRITE (NOUT,9020) NUM, LABOUT      GO TO 5000C  270 IF (LFM .EQ. 0 .AND. BEFORE) THEN        NBE = .FALSE.        GO TO 5000      ENDIF      IF (.NOT. BEFORE) THEN        DO 275 J = 1, 6        J2MOD = MOD(J-1,2) + 1        VMO(J) = VM(J)/UMIS(J2MOD)  275   CONTINUE      ENDIFC      CALL CMISDO(CMIS)C      LABMIS = LABEL(NMIS)(1:10)      IF (LFM .GE. 1) GO TO 280      WRITE (NOUT,9080) NUM, LABMIS, VMO(1), XMIS(1),     1                  VMO(2), XMIS(2), VMO(3), XMIS(1),     2                  VMO(4), XMIS(2), VMO(5), XMIS(1),     3                  VMO(6), XMIS(2), CMIS      GO TO 5000C  280 IF (.NOT. BEFORE) GO TO 285      WRITE (NOUT,9062) NUM, LABMIS      GO TO 5000C  285 WRITE (NOUT,9081) NUM, LABMIS,     1                  VMO(1), XMIS(1), VMO(2), XMIS(2),     2                  VMO(3), XMIS(1), VMO(4), XMIS(2),     3                  VMO(5), XMIS(1), VMO(6), XMIS(2),     4                  CMIS      GO TO 5000CC     3. -- DRIFT SPACEC  300 IF (PRON .AND. ELPR) THEN        IF (.NOT. SUPP) THEN          LOUT = L/UNITO(8)          WRITE (NOUT,9030) NUM, LABOUT, LOUT, XDIME(8)        ELSE          WRITE (NOUT,9030) NUM, LABOUT        ENDIF      ENDIF      GO TO 5000CC     4. -- BENDING MAGNETC  400 IF (.NOT. (PRON .AND. ELPR)) GO TO 5000      IF (TYPEC .EQ. 8) GO TO 470      IF (SUPP) GO TO 450      IK1 = IPTOJ(NK1)C      DO 410 NPAR = NRMPS, NK3      IPAR = IPTOJ(NPAR)      VARIED = TIE(I+IPAR) .NE. 0 .AND. TIE(I+IPAR) .LT. 99      IF (IPAR .EQ. 0 .AND. VARIED) GO TO 410      IF (.NOT. VARIED .AND. PRAN4(NPAR) .EQ. 0.0) GO TO 410      IF (NPAR .EQ. NRMPS) PARAM = RMPS      IF (NPAR .EQ. NRNMS) PARAM = RNMS      IF (NPAR .EQ. NVR) PARAM = VRN      IF (NPAR .EQ. NNP) PARAM = NPN      IF (NPAR .EQ. NK1P) PARAM = K1P*UNITO(8)**2      IF (NPAR .EQ. NBDB) PARAM = BDB      IF (NPAR .EQ. NK2) THEN        PARAM = K2*UNITO(8)**3        IF (MPMAD) PARAM = 2.0*PARAM      ENDIF      IF (NPAR .EQ. NBDBP) PARAM = BDBP      IF (NPAR .EQ. NK2P) THEN        PARAM = K2P*UNITO(8)**3        IF (MPMAD) PARAM = 2.0*PARAM      ENDIF      IF (NPAR .EQ. NGAM) PARAM = GAM      IF (NPAR .EQ. NK3) THEN        PARAM = K3*UNITO(8)**3        IF (MPMAD) PARAM = 6.0*PARAM      ENDIF      WRITE (NOUT,9160) NUM, DBEND(NPAR), BLANK, PARAM  410 CONTINUEC      LOUT = LBEND/UNITO(8)      IF (H0 .EQ. 0.0) THEN        RHONRM = 0.0      ELSE        RHONRM = 1.0/(H0*UNITO(8))      ENDIF      ALNORM = AL/UNITO(7)      IF (RI .EQ. 0.0) GO TO 430      BNORM = (1.0 + RMPS)*B/UNITO(9)      IF (IK1 .NE. 0 .OR. PRAN4(6) .NE. 0.0) GO TO 420      IF (RHONRM .GE. 1000000.0 .OR. RHONRM .LE. -100000.0) GO TO 418      WRITE (NOUT,9040) NUM, KELEM(TYPE), LABOUT, LOUT, XDIME(8),     1                  BNORM, XDIME(9), NB, RHONRM, XDIME(8),     2                  ALNORM, XDIME(7)      GO TO 5000C  418 WRITE (NOUT,9044) NUM, KELEM(TYPE), LABOUT, LOUT, XDIME(8),     1                  BNORM, XDIME(9), NB, ALNORM, XDIME(7)      GO TO 5000C  420 K1NORM = K1*UNITO(8)**2      WRITE (NOUT,9041) NUM, KELEM(4), LABOUT, LOUT, XDIME(8),     1                  BNORM, XDIME(9), K1NORM, XDIME(8),     2                  RHONRM, XDIME(8), ALNORM, XDIME(7)      GO TO 5000C  430 IF (IK1 .NE. 0) GO TO 435      WRITE (NOUT,9042) NUM, KELEM(4), LABOUT, LOUT, XDIME(8),     1                  NB, RHONRM, XDIME(8), ALNORM, XDIME(7)      GO TO 5000C  435 K1NORM = K1*UNITO(8)**2      WRITE (NOUT,9043) NUM, KELEM(4), LABOUT, LOUT, XDIME(8),     1                  K1NORM, XDIME(8), RHONRM, XDIME(8),     2                  ALNORM, XDIME(7)      GO TO 5000C  450 WRITE (NOUT,9040) NUM, KELEM(4), LABOUT      IF (RORC .NE. 3 .AND. RORC .NE. 4) GO TO 5000      WRITE (NOUT,9080) NUM, LABMIS      GO TO 5000C  470 LABMIS = LABEL(NMIS)(1:10)      IF (LFM .EQ. 0 .AND. BEFORE) THEN        NBE = .FALSE.        GO TO 5000      ENDIF      CALL CMISDO(CMIS)      IF (.NOT. BEFORE) THEN        DO 475 J = 1, 6        J2MOD = MOD(J-1,2) + 1        VMO(J) = VM(J)/UMIS(J2MOD)  475   CONTINUE      ENDIFC      IF (LFM .GE. 1) GO TO 480      WRITE (NOUT,9080) NUM, LABMIS,     1                  VMO(1), XMIS(1), VMO(2), XMIS(2),     2                  VMO(3), XMIS(1), VMO(4), XMIS(2),     3                  VMO(5), XMIS(1), VMO(6), XMIS(2),     4                  CMIS      GO TO 5000C  480 IF (.NOT. BEFORE) GO TO 485      WRITE (NOUT,9062) NUM, LABMIS      GO TO 5000C  485 WRITE (NOUT,9081) NUM, LABMIS,     1                  VMO(1), XMIS(1), VMO(2), XMIS(2),     2                  VMO(3), XMIS(1), VMO(4), XMIS(2),     3                  VMO(5), XMIS(1), VMO(6), XMIS(2),     4                  CMIS      GO TO 5000CC     5. -- QUADRUPOLEC  500 IF (.NOT. (PRON .AND. ELPR)) GO TO 5000      IF (TYPEC .EQ. 20) GO TO 560      IF (TYPEC .EQ. 8) GO TO 570C  510 IF (SUPP) GO TO 565      LOUT = LMAG/UNITO(8)      IF (NORD1 .LT. 1) THEN        SKX = 0.0      ELSE        SKX = - KX2 * SX      ENDIF      IF (SKX .EQ. 0.0) THEN        CWORK1 = '   INFINITE'      ELSE        WORK1 = -1.0/(SKX*UNITO(8))        IF (ABS(WORK1) .GT. 100000.0) THEN          WRITE (CWORK1,9054) WORK1        ELSE          WRITE (CWORK1,9053) WORK1        ENDIF       ENDIFC  530 IG = IPTOJ(4)      IK1 = IPTOJ(5)      IF (IG .NE. 0) GO TO 540      IF (IK1 .NE. 0) GO TO 545      BNORM = B/UNITO(9)      APOUT = AP/UNITO(1)      WRITE (NOUT,9050) NUM, LABOUT, LOUT, XDIME(8), BNORM, XDIME(9),     1                  APOUT, XDIME(1), CWORK1, XDIME(8)      GO TO 5000C  540 GNORM = GRAD*UNITO(1)/UNITO(9)      WRITE (NOUT,9051) NUM, LABOUT, LOUT, XDIME(8), GNORM, XDIME(9),     1                  XDIME(1), CWORK1, XDIME(8)      GO TO 5000C  545 WRITE (NOUT,9052) NUM, LABOUT, LOUT, XDIME(8), K1, XDIME(8),     1                  CWORK1, XDIME(8)      GO TO 5000C  560 THOUT = TH/UNITO(13)      WRITE (NOUT,9200) NUM, BLANK, THOUT, XDIME(13)      GO TO 5000C  565 WRITE (NOUT,9050) NUM, LABOUT      IF (RORC .NE. 3 .AND. RORC .NE. 5) GO TO 5000      WRITE (NOUT,9080) NUM, LABMIS      GO TO 5000C  570 IF (LFM .EQ. 0 .AND. BEFORE) THEN        NBE = .FALSE.        GO TO 5000      ENDIF      IF (.NOT. BEFORE) THEN        DO 575 J = 1, 6        J2MOD = MOD(J-1,2) + 1        VMO(J) = VM(J)/UMIS(J2MOD)  575   CONTINUE      ENDIFC      CALL CMISDO(CMIS)C      LABMIS = LABEL(NMIS)(1:10)      IF (LFM .GE. 1) GO TO 580      WRITE (NOUT,9080) NUM, LABMIS,     1                  VMO(1), XMIS(1), VMO(2), XMIS(2),     2                  VMO(3), XMIS(1), VMO(4), XMIS(2),     3                  VMO(5), XMIS(1), VMO(6), XMIS(2),     4                  CMIS      GO TO 5000C  580 IF (.NOT. BEFORE) GO TO 585      WRITE (NOUT,9062) NUM, LABMIS      GO TO 5000C  585 WRITE (NOUT,9081) NUM, LABMIS,     1                  VMO(1), XMIS(1), VMO(2), XMIS(2),     2                  VMO(3), XMIS(1), VMO(4), XMIS(2),     3                  VMO(5), XMIS(1), VMO(6), XMIS(2),     4                  CMIS      GO TO 5000CC     6. -- UPDATEC  600 NBE = .FALSE.      NRT = .FALSE.      IF (.NOT. (PRON .AND. ELPR)) GO TO 5000      IF (TYPEC .EQ. 8) GO TO 650      IF (JA .NE. 0) GO TO 620      IF (SUPP) GO TO 610      LABUPD = BLANK      IF (JA .EQ. 0 .AND. KA .EQ. 1) LABUPD = 'R1'      IF (JA .EQ. 0 .AND. KA .EQ. 2) LABUPD = 'R2'      WRITE (NOUT,9060) NUM, LABOUT, LABUPD      GO TO 5000C  610 WRITE (NOUT,9060) NUM, LABOUT      GO TO 5000C  620 IF (SUPP) GO TO 630      WIDTH = DATA(I+2)      JAX = MOD(JA,100)      WRITE (NOUT,9061) NUM, LABOUT, JA, WIDTH, XDIME(JAX)      GO TO 5000C  630 WRITE (NOUT,9061) NUM, LABOUT      GO TO 5000C  650 IF (RORC .GE. 3 .AND. LFM .GE. 2) GO TO 5000      NBE = .TRUE.      LABMIS = LABEL(NMIS)(1:10)      WRITE (NOUT,9062) NUM, LABMIS      GO TO 5000CC     7. -- BEAM CENTROID SHIFTC  700 NRT = .FALSE.      IF (.NOT. (PRON .AND. ELPR)) GO TO 5000      IF (.NOT. SUPP) THEN        DO 710 J = 1, 6  710   CODO(J) = COD(J)/UNITO(J)        WRITE (NOUT,9070) NUM, LABOUT, (CODO(J), XDIME(J), J = 1, 6)      ELSEC        WRITE (NOUT,9070) NUM, LABOUT      ENDIF      GO TO 5000CC     8. -- MAGNET MISALIGNMENTC  800 NRT = LFM .GE. 1 .AND. LTAB .EQ. 0      LABMIS = LABEL(NUM)(1:10)      IF (RORC .GE. 3) THEN        NBE = .FALSE.        GO TO 5000      ENDIF      IF (.NOT. (PRON .AND. ELPR)) GO TO 5000      IF (SUPP) GO TO 820      DO 805 J = 1, 6      J2MOD = MOD(J-1,2) + 1      VMO(J) = VM(J)/UMIS(J2MOD)  805 CONTINUEC      CALL CMISDO(CMIS)C      IF (LFM .EQ. 1) GO TO 810      WRITE (NOUT,9080) NUM, LABMIS,     1           VMO(1), XMIS(1), VMO(2), XMIS(2), VMO(3), XMIS(1),     2           VMO(4), XMIS(2), VMO(5), XMIS(1), VMO(6), XMIS(2),     3           CMIS      GO TO 5000C  810 WRITE (NOUT,9081) NUM, LABMIS,     1           VMO(1), XMIS(1), VMO(2), XMIS(2), VMO(3), XMIS(1),     2           VMO(4), XMIS(2), VMO(5), XMIS(1), VMO(6), XMIS(2),     3           CMIS      GO TO 5000C  820 WRITE (NOUT,9080) NUM, LABOUT      GO TO 5000CC     10. -- FITTING CONSTRAINTSC 1000 NBE = .FALSE.      IF (.NOT. (PRON .AND. ELPR)) GO TO 5000      IF (CTY .EQ. 0) SLANG = '*FIT*'      IF (CTY .EQ. 1) SLANG = '*LOW.LIM.*'      IF (CTY .EQ. 2) SLANG = '*UP.LIM.*'      IF (SUPP) GO TO 1030      CALL NAME10C      IF (LSTEP .AND. BROAD) THEN        FSTEPS = FLOAT(NSTEPS)        ID1 = IPTOJ(10)        ID2 = IPTOJ(11)        COC = DATA(I+ID1)/FSTEPS        COC2 = DATA(I+ID2)/FSTEPS - COC**2        COC2 = SQRT(COC2)      ENDIFC      IF (DE0 .EQ. 0.0) THEN        CDE0 = '       0.0'      ELSE IF (ABS(DE0) .GE. 0.0001) THEN        WRITE (CDE0,9107) DE0      ELSE        WRITE (CDE0,9108) DE0      ENDIFC      IF (ABS(SD) .GE. 0.0001 .AND. ABS(SD) .LT. 10.0) THEN        WRITE (CSD,9109) SD      ELSE        WRITE (CSD,9111) SD      ENDIFC      IF (JCON .GT. -20 .AND. JCON .LT. -10 .AND. JCON .NE. -15) THEN        IF (ABS(COC) .LE. 2.0) THEN          COC = COCO        ELSE          COC = 0.5*COC          GO TO 1020        ENDIF      ENDIFC      IF (COC .EQ. 0.0) THEN        CCOC = '     0.0'      ELSE IF (ABS(COC) .GE. 0.0001) THEN        WRITE (CCOC,9104) COC      ELSE        WRITE (CCOC,9105) COC      ENDIFC      IF (LSTEP .AND. BROAD) THEN        IF (COC2 .EQ. 0.0) THEN          CCOC2 = '     0.0'        ELSE IF (ABS(COC2) .GE. 0.0001) THEN          WRITE (CCOC2,9104) COC2        ELSE          WRITE (CCOC2,9105) COC2        ENDIF      ENDIFC      IF (LSTEP .AND. BROAD) GO TO 1010      IF (NARROW) THEN        WRITE (NOUT,9102) NUM, SLANG, LABOUT, FTNAME, CDE0, CSD, CCOC      ELSE        WRITE (NOUT,9100) NUM, SLANG, LABOUT, FTNAME, CDE0, CSD, CCOC      ENDIF      GO TO 5000C 1010 IF (NARROW) THEN        WRITE (NOUT,9112) NUM, SLANG, LABOUT, FTNAME, CDE0, CSD, CCOC,     1                    CCOC2      ELSE        WRITE (NOUT,9113) NUM, SLANG, LABOUT, FTNAME, CDE0, CSD, CCOC,     1                    CCOC2      ENDIF      GO TO 5000C 1020 WRITE (CACOC,9106) COC      IF (NARROW) THEN        WRITE (NOUT,9103) NUM, SLANG, LABOUT, FTNAME, CDE0, CSD, CACOC      ELSE        WRITE (NOUT,9101) NUM, SLANG, LABOUT, FTNAME, CDE0, CSD, CACOC      ENDIF      GO TO 5000C 1030 WRITE (NOUT,9100) NUM, SLANG, LABOUT      GO TO 5000CC     11. -- ACCELERATORC 1100 IF (.NOT. (PRON .AND. ELPR)) GO TO 5000      IF (SUPP) GO TO 1110      LOUT = L/UNITO(8)      EGOUT = EGAIN/UNITO(11)      WORK1 = RI/UNITO(11)      PHOUT = PHASEL*RADIAN      WOUT = WAVEL/UNITO(5)      WRITE (NOUT,9110) NUM, LABOUT, LOUT, XDIME(8), EGOUT,     1                  WORK1, XDIME(11), PHOUT, WOUT      GO TO 5000C 1110 WRITE (NOUT,9110) NUM, LABOUT      GO TO 5000CC     12. -- CORRELATIONS IN BEAM ELLIPSEC 1200 IF (.NOT. (PRON .AND. ELPR)) GO TO 5000      IF (IVA .NE. 0) WRITE (NOUT,9120) NUM, LABOUT      NRT = .FALSE.      GO TO 5000CC     13. -- INPUT-OUTPUT OPTIONSC 1300 NBE = .FALSE.      IF (PRON .AND. ELPR .AND. .NOT. ONLY) THEN        IF (CDB .EQ. 9) WRITE (NOUT,9130) NUM, LABOUT        IF (CDB .EQ. 11) WRITE (NOUT,9131) NUM, LABOUT        IF (CDB .EQ. 9 .OR. CDB .EQ. 11) LCPR = .FALSE.      ENDIF      CALL IO      GO TO 5000CC     14. -- ARBITRARY MATRIXC 1400 IF (.NOT. (PRON .AND. ELPR)) GO TO 5000      IF (I14S .NE. 0) THEN        WRITE (NOUT,9140) NUM, LABOUT, J1      ELSE IF (I14T .NE. 0) THEN        WRITE (NOUT,9141) NUM, LABOUT, J1      ELSE        WRITE (NOUT,9142) NUM, LABOUT, J1      ENDIF      IF (NUM + 1 .GT. NEL) GO TO 5000      IF (NEXT .EQ. 14) NBE = .FALSE.      GO TO 5000CC     16. -- SPECIAL PARAMETERSC 1600 NBE = .FALSE.      NRT = .FALSE.      IF (.NOT. (PRON .AND. ELPR)) GO TO 5000      J = NPARS      IF (NPARS .EQ. 100) J = 28      IF (NPARS .EQ. 101) J = 29      IF (NPARS .EQ. 102) J = 30      IF (J .GT. 30) GO TO 5000      PNAME = DSPEC(J+3)(1:8)      IF (SUPP) GO TO 1620      IF (NPARS .EQ. 14) GO TO 1610      WRITE (NOUT,9160) NUM, PNAME, LABOUT, PARAM      GO TO 5000C 1610 DO 1611 J = 1, 4      J1 = 4*J - 3      J2 = J1 + 3      WRITE (NUMREP(J1:J2),9162) ISEEDX(J) 1611 CONTINUE       DO 1612 J = 2, 4      DO 1612 K = 1, 4      JK = 4*J + K - 4      IF (NUMREP(JK:JK) .EQ. ' ') NUMREP(JK:JK) = '0' 1612 CONTINUE      WRITE (NOUT,9161) NUM, PNAME, LABOUT, NUMREP      GO TO 5000C 1620 WRITE (NOUT,9160) NUM, PNAME, LABOUT      GO TO 5000CC     17. -- SECOND ORDER CALCULATIONC 1700 NBE = .FALSE.      IF (.NOT. (PRON .AND. ELPR)) GO TO 5000      IF (NORDX .EQ. 3) GO TO 1720      IF (NORDX .EQ. 2) GO TO 1710      WRITE (NOUT,9170) NUM, LABOUT, NORDX, NORD3      GO TO 5000C 1710 WRITE (NOUT,9171) NUM, LABOUT, NORDX, NORD3      GO TO 5000C 1720 WRITE (NOUT,9172) NUM, LABOUT, NORDX, NORD3      GO TO 5000CC     18. -- SEXTUPOLEC 1800 IF (.NOT. (PRON .AND. ELPR)) GO TO 5000      IF (TYPEC .EQ. 20) GO TO 1820      IF (TYPEC .EQ. 8) GO TO 1830      IF (SUPP) GO TO 1840C 1810 LOUT = LMAG/UNITO(8)      IK2 = IPTOJ(4)      IF (IK2 .NE. 0) GO TO 1815      BNORM = B/UNITO(9)      APOUT = AP/UNITO(1)      WRITE (NOUT,9180) NUM, LABOUT, LOUT, XDIME(8), BNORM, XDIME(9),     1                  APOUT, XDIME(1)      GO TO 5000C 1815 K2OUT = K2*UNITO(8)**3      IF (MPMAD) K2OUT = 2.0*K2OUT      WRITE (NOUT,9181) NUM, LABOUT, LOUT, XDIME(8), K2OUT, XDIME(8)      GO TO 5000C 1820 IF (SUPP) GO TO 1825      THOUT = TH/UNITO(13)      WRITE (NOUT,9200) NUM, BLANK, THOUT, XDIME(13)      GO TO 5000C 1825 WRITE (NOUT,9200) NUM      GO TO 5000C 1830 IF (RORC .NE. 3) GO TO 5000      IF (TYT .LT. 200) GO TO 5000      CALL CMISDO(CMIS)      DO 1835 J = 1, 6      J2MOD = MOD(J-1,2) + 1      VMO(J) = VM(J)/UMIS(J2MOD) 1835 CONTINUE      LABMIS = LABEL(NMIS)(1:10)      WRITE (NOUT,9080) NUM, LABMIS,     1                  VMO(1), XMIS(1), VMO(2), XMIS(2),     2                  VMO(3), XMIS(1), VMO(4), XMIS(2),     3                  VMO(5), XMIS(1), VMO(6), XMIS(2),     3                  CMIS      GO TO 5000C 1840 WRITE (NOUT,9180) NUM, LABOUT      IF (RORC .NE. 3) GO TO 5000      WRITE (NOUT,9080) NUM, LABMIS      GO TO 5000CC     19. -- SOLENOIDC 1900 IF (.NOT. (PRON .AND. ELPR)) GO TO 5000      IF (SUPP) GO TO 1920      LOUT = L/UNITO(8)      FLEN = - R(2,1)/(SQRT(R(1,1))*UNITO(8))      ANORM = 0.5*KL/UNITO(13)      IK = IPTOJ(3)      IF (IK .NE. 0) GO TO 1910      BNORM = B/UNITO(9)      WRITE (NOUT,9190) NUM, LABOUT, LOUT, XDIME(8), BNORM, XDIME(9),     1                  FLEN, XDIME(8), ANORM, XDIME(13)      GO TO 5000C 1910 WRITE (NOUT,9191) NUM, LABOUT, LOUT, XDIME(8), ANORM      GO TO 5000C 1920 WRITE (NOUT,9190) NUM, LABOUT      GO TO 5000CC     20. -- BEAM ROTATIONC 2000 IF (.NOT. (PRON .AND. ELPR)) GO TO 5000      TYPEN = IDATA(ISTOR(NUM+NDIF))      IF (REFER .AND. (TYPEN .EQ. 2 .OR. TYPEN .EQ. 4     1    .OR. TYPEN .EQ. 5 .OR. TYPEN .EQ. 18     2    .OR. TYPEN .EQ. 25 .OR. TYPEN .EQ. 28     3    .OR. TYPEN .EQ. 29)) SONLY = .TRUE.      IF (SUPP) GO TO 2010      THOUT = TH/UNITO(13)      WRITE (NOUT,9200) NUM, LABOUT, THOUT, XDIME(13)      GO TO 5000C 2010 WRITE (NOUT,9200) NUM, LABOUT      GO TO 5000CC     21. -- STRAY FIELDC 2100 NRT = .FALSE.      IF (.NOT. (PRON .AND. ELPR)) GO TO 5000      IF (SUPP) GO TO 2110      WRITE (NOUT,9210) NUM, LABOUT, DATA(I+1), DATA(I+2), DATA(I+3)      GO TO 5000C 2110 WRITE (NOUT,9210) NUM, LABOUT      GO TO 5000CC     25. -- OCTUPOLEC 2500 IF (.NOT. (PRON .AND. ELPR)) GO TO 5000      IF (TYPEC .EQ. 20) GO TO 2520      IF (SUPP) GO TO 2550C 2510 LOUT = LMAG/UNITO(8)      IK3 = IPTOJ(4)      IF (IK3 .NE. 0) GO TO 2515      BNORM = B/UNITO(9)      APOUT = AP/UNITO(1)      WRITE (NOUT,9250) NUM, LABOUT, LOUT, XDIME(8), BNORM, XDIME(9),     1                  APOUT, XDIME(1)      GO TO 5000C 2515 K3OUT = K3*UNITO(8)**3      IF (MPMAD) K3OUT = 6.0*K3OUT      WRITE (NOUT,9251) NUM, LABOUT, LOUT, XDIME(8), K3OUT, XDIME(8)      GO TO 5000C 2520 THOUT = TH/UNITO(13)      WRITE (NOUT,9200) NUM, BLANK, THOUT, XDIME(13)      GO TO 5000C 2550 WRITE (NOUT,9250) NUM, LABOUT      GO TO 5000CC     27. -- ACCELERATOR FUNCTION ETAC 2700 IF (.NOT. (PRON .AND. ELPR)) GO TO 5000      DO 2705 J = 1, 6 2705 CODO(J) = ETA(J)/UNITO(J)      IF (.NOT. (ACCEL .OR. LTWISS)) GO TO 2720      IF (SUPP) GO TO 2710      WRITE (NOUT,9270) NUM, LABOUT, (CODO(J), XDIME(J), J = 1, 6)      GO TO 5000C 2710 WRITE (NOUT,9270) NUM, LABOUT      GO TO 5000C 2720 IF (SUPP) GO TO 2730      WRITE (NOUT,9271) NUM, LABOUT, (CODO(J), XDIME(J), J = 1, 6)      GO TO 5000C 2730 WRITE (NOUT,9271) NUM, LABOUT      GO TO 5000CC     28. -- RECTANGULAR BEND MAGNET (INCLUDING FRINGE FIELDS)C                           ORC     29. -- SECTOR BEND MAGNET (INCLUDING FRINGE FIELDS)C 2800 IF (.NOT. (PRON .AND. ELPR)) GO TO 5000      IF (SUPP) GO TO 2890      IF (TYPEC .EQ. 8) GO TO 2870      IF (TYPEC .EQ. 20) GO TO 2860      IF (TYPEC .EQ. 4) GO TO 2820      IF (TYPEC .EQ. 2 .AND. BEFORE) GO TO 2810      IF (TYPEC .EQ. 2 .AND. .NOT. BEFORE) GO TO 2850      GO TO 5000C 2810 BEO = BE1/UNITO(7)      IF (NORD1 .EQ. 1) THEN        WRITE (NOUT,9281) NUM, LABOUT, BEO, XDIME(7)      ELSE        IF (NDIF .EQ. 1) THEN          RABO = RAB1*UNITO(8)        ELSE          RABO = RAB2*UNITO(8)        ENDIF        IF (RABO .NE. 0.0) THEN          WRITE (NOUT,9281) NUM, LABOUT, BEO, XDIME(7), RABO, XDIME(8)        ELSE          WRITE (NOUT,9281) NUM, LABOUT, BEO, XDIME(7)        ENDIF      ENDIF      GO TO 5000C 2820 IK1 = IPTOJ(NK1)      NRMPS = 7      NK3 = 21C      DO 2825 NPAR = NRMPS, NK3      IPAR = IPTOJ(NPAR)      IF (NPAR .EQ. NE1 .OR. NPAR .EQ. NE2 .OR. NPAR .EQ. NH1     1    .OR. NPAR .EQ. NH2) GO TO 2825      VARIED = TIE(I+IPAR) .NE. 0 .AND. TIE(I+IPAR) .LT. 99      IF (IPAR .EQ. 0 .AND. VARIED) GO TO 2825      IF (.NOT. VARIED .AND. PRAN28(NPAR) .EQ. 0.0) GO TO 2825      IF (NPAR .EQ. NRMPS) PARAM = RMPS      IF (NPAR .EQ. NVR) PARAM = VRN      IF (NPAR .EQ. NNP) PARAM = NPN      IF (NPAR .EQ. NK1P) PARAM = K1P*UNITO(8)**2      IF (NPAR .EQ. NRNMS) PARAM = RNMS      IF (NPAR .EQ. NBDB) PARAM = BDB      IF (NPAR .EQ. NK2) THEN        PARAM = K2*UNITO(8)**3        IF (MPMAD) PARAM = 2.0*PARAM      ENDIF      IF (NPAR .EQ. NBDBP) PARAM = BDBP      IF (NPAR .EQ. NK2P) THEN        PARAM = K2P*UNITO(8)**3        IF (MPMAD) PARAM = 2.0*PARAM      ENDIF      IF (NPAR .EQ. NGAM) PARAM = GAM      IF (NPAR .EQ. NK3) THEN        PARAM = K3*UNITO(8)**4        IF (MPMAD) PARAM = 6.0*PARAM      ENDIF      WRITE (NOUT,9160) NUM, DRBND(NPAR), BLANK, PARAM 2825 CONTINUEC      IF (TYPE .EQ. 28) THEN        LOUT = LRBEND/UNITO(8)        NN = 28      ELSE IF (TYPE .EQ. 29) THEN        LOUT = LBEND/UNITO(8)        NN = 29      ELSE        LOUT = LBEND/UNITO(8)        NN = 4      ENDIF      IF (H0 .EQ. 0.0) THEN        RHONRM = 0.0      ELSE        RHONRM = 1.0/(H0*UNITO(8))      ENDIF      ALNORM = AL/UNITO(7)      IF (RI .EQ. 0.0) GO TO 2830      BNORM = (1.0 + RMPS)*B/UNITO(9)      IF (IK1 .NE. 0) GO TO 2828      IF (RHONRM .GE. 1000000.0 .OR. RHONRM .LE. -100000.0) GO TO 2827      WRITE (NOUT,9040) NUM, KELEM(NN), LABOUT, LOUT, XDIME(8),     1                  BNORM, XDIME(9), NB, RHONRM, XDIME(8),     2                  ALNORM, XDIME(7)      GO TO 5000C 2827 WRITE (NOUT,9044) NUM, KELEM(NN), LABOUT, LOUT, XDIME(8),     1                  BNORM, XDIME(9), NB, ALNORM, XDIME(7)      GO TO 5000C 2828 K1NORM = K1*UNITO(8)**2      WRITE (NOUT,9041) NUM, KELEM(NN), LABOUT, LOUT, XDIME(8),     1                  BNORM, XDIME(9), K1NORM, XDIME(8),     2                  RHONRM, XDIME(8), ALNORM, XDIME(7)      GO TO 5000C 2830 IF (IK1 .NE. 0) GO TO 2835      WRITE (NOUT,9042) NUM, KELEM(NN), LABOUT, LOUT, XDIME(8),     1                  NB, RHONRM, XDIME(8), ALNORM, XDIME(7)      GO TO 5000  2835 K1NORM = K1*UNITO(8)**2      WRITE (NOUT,9043) NUM, KELEM(NN), LABOUT,     1                  LOUT, XDIME(8), K1NORM, XDIME(8),     2                  RHONRM, XDIME(8), ALNORM, XDIME(7)      GO TO 5000C 2850 BEO = BE2/UNITO(7)      IF (NORD1 .EQ. 1) THEN        WRITE (NOUT,9281) NUM, LABOUT, BEO, XDIME(7)      ELSE        IF (NDIF .EQ. 1) THEN          RABO = RAB2*UNITO(8)        ELSE          RABO = RAB1*UNITO(8)        ENDIF        IF (RABO .NE. 0.0) THEN          WRITE (NOUT,9281) NUM, LABOUT, BEO, XDIME(7),     1                      RABO, XDIME(8)        ELSE          WRITE (NOUT,9281) NUM, LABOUT, BEO, XDIME(7)        ENDIF      ENDIF      GO TO 5000C 2860 THOUT = TH/UNITO(13)      WRITE (NOUT,9200) NUM, BLANK, THOUT, XDIME(13)      GO TO 5000C 2870 CALL CMISDO(CMIS)      IF (.NOT. BEFORE) THEN        DO 2875 J = 1, 6        J2MOD = MOD(J-1,2) + 1        VMO(J) = VM(J)/UMIS(J2MOD) 2875   CONTINUE      ENDIFC      CALL CMISDO(CMIS)C      LABMIS = LABEL(NMIS)(1:10)      IF (LFM .GE. 1) GO TO 2880      WRITE (NOUT,9080) NUM, LABMIS,     1                  VMO(1), XMIS(1), VMO(2), XMIS(2),     2                  VMO(3), XMIS(1), VMO(4), XMIS(2),     3                  VMO(5), XMIS(1), VMO(6), XMIS(2),     4                  CMIS      GO TO 5000C 2880 IF (.NOT. BEFORE) GO TO 2885      IF (PRON .AND. ELPR) WRITE (NOUT,9062) NUM, LABMIS      GO TO 5000C 2885 WRITE (NOUT,9081) NUM, LABMIS,     1                  VMO(1), XMIS(1), VMO(2), XMIS(2),     2                  VMO(3), XMIS(1), VMO(4), XMIS(2),     3                  VMO(5), XMIS(1), VMO(6), XMIS(2),     4                  CMIS      GO TO 5000C 2890 WRITE (NOUT,9040) NUM, KELEM(TYPE), LABOUT      GO TO 5000CC     31. -- MARKERC 3100 IF (.NOT. (PRON .AND. ELPR)) GO TO 5000      WRITE (NOUT,9310) NUM, LABOUT      GO TO 5000CC     33. -- STORED MATRIX ELEMENT OR ALGEBRAIC EXPRESSIONC 3300 NBE = .FALSE.      IF (SUPP) GO TO 5000      IF (LABEL(NUM) .EQ. BLANK) GO TO 5000      WRITE (NOUT,9330) NUM, LABOUT, PARAM      GO TO 5000CC     34. -- PLASMA LENSC 3400 IF (.NOT. (PRON .AND. ELPR)) GO TO 5000      IF (SUPP) GO TO 3470      LOUT = LMAG/UNITO(8)      IF (NORD1 .LT. 1) GO TO 3415      SKX = - KX2 * SX      IF (SKX .NE. 0.0) GO TO 3420 3415 WORK1 = 0.0      GO TO 3430 3420 WORK1 = 1.0/(SKX*UNITO(8))C 3430 IG = IPTOJ(4)      IK1 = IPTOJ(5)      IF (IG .NE. 0) GO TO 3440      IF (IK1 .NE. 0) GO TO 3445      BNORM = B/UNITO(9)      APOUT = AP/UNITO(1)      WRITE (NOUT,9340) NUM, LABOUT, LOUT, XDIME(8), BNORM,     1                  XDIME(9), APOUT, XDIME(1), WORK1, XDIME(8)      GO TO 5000C 3440 GNORM = GRAD*UNITO(1)/UNITO(9)      WRITE (NOUT,9341) NUM, LABOUT, LOUT,     1                  XDIME(8), GNORM, XDIME(9), XDIME(1),     2                  WORK1, XDIME(8)      GO TO 5000C 3445 IF (ABS(K1) .GT. 0.01) THEN        WRITE (NOUT,9342) NUM, LABOUT, LOUT,     1                    XDIME(8), K1, XDIME(8), WORK1, XDIME(8)      ELSE        WRITE (NOUT,9343) NUM, LABOUT, LOUT,     1                    XDIME(8), K1, XDIME(8), WORK1, XDIME(8)      ENDIF      GO TO 5000C 3470 WRITE (NOUT,9340) NUM, LABOUT      GO TO 5000CC     35. -- HKICK -- HORIZONTAL VERNIERC 3500 IF (.NOT. (PRON .AND. ELPR)) GO TO 5000      IF (TYPEC .EQ. 20) GO TO 3560      IF (SUPP) GO TO 3550      LOUT = LBEND/UNITO(8)      BNORM = B/UNITO(9)      ALNORM = AL/UNITO(7)      IF (L .EQ. 0.0 .AND. AL .NE. 0.0) GO TO 3510      WRITE (NOUT,9350) NUM, LABOUT, LOUT, XDIME(8), BNORM, XDIME(9),     1                  ALNORM, XDIME(7)      GO TO 5000C 3510 WRITE (NOUT,9351) NUM, LABOUT, LOUT, XDIME(8), ALNORM, XDIME(7)      GO TO 5000C 3550 WRITE (NOUT,9350) NUM, LABOUT      GO TO 5000C 3560 IF (SUPP) GO TO 3565      THOUT = TH/UNITO(13)      WRITE (NOUT,9200) NUM, BLANK, THOUT, XDIME(13)      GO TO 5000C 3565 WRITE (NOUT,9200) NUM, BLANK      GO TO 5000CC     36. -- VKICK -- VERTICAL VERNIERC 3600 IF (.NOT. (PRON .AND. ELPR)) GO TO 5000      IF (TYPEC .EQ. 20) GO TO 3660      IF (SUPP) GO TO 3650      LOUT = LBEND/UNITO(8)      BNORM = B/UNITO(9)      ALNORM = AL/UNITO(7)      IF (L .EQ. 0.0 .AND. AL .NE. 0.0) GO TO 3610      WRITE (NOUT,9360) NUM, LABOUT, LOUT, XDIME(8), BNORM,     1                  XDIME(9), ALNORM, XDIME(7)      GO TO 5000C 3610 WRITE (NOUT,9361) NUM, LABOUT, LOUT, XDIME(8), ALNORM, XDIME(7)      GO TO 5000C 3650 WRITE (NOUT,9360) NUM, LABOUT      GO TO 5000C 3660 IF (SUPP) GO TO 3665      NROT35 = 5      THROT = DATA(I+IPTOJ(NROT35))      THOUT = THROT      IF (.NOT. BEFORE) THOUT = - THOUT      WRITE (NOUT,9200) NUM, BLANK, THOUT, XDIME(13)      GO TO 5000C 3665 WRITE (NOUT,9200) NUM, BLANK      GO TO 5000CC     37. -- ALIGNMENT MARKERC 3700 IF (TYPEC .EQ. 8) GO TO 3750      NBE = .FALSE.      NRT = .FALSE.      IF (.NOT. (PRON .AND. ELPR)) GO TO 5000      IF (JA .NE. 0 .OR. NUNC .EQ. 0) GO TO 5000      IF (SUPP) GO TO 3710      LABUPD = BLANK      IF (JA .EQ. 0 .AND. KA .EQ. 1) LABUPD = 'R'      IF (JA .EQ. 0 .AND. KA .EQ. 2) LABUPD = 'R2'      WRITE (NOUT,9370) NUM, LABOUT, LABUPD      GO TO 5000C 3710 WRITE (NOUT,9370) NUM, LABOUT      GO TO 5000C 3750 IF (RORC .GE. 3 .AND. LFM .GE. 2) GO TO 5000      LABMIS = LABEL(NMIS)(1:10)      IF (PRON .AND. ELPR) WRITE (NOUT,9372) NUM, LABMIS      GO TO 5000CC     38. -- PLOTTINGC 3800 NBE = .FALSE.      IF (NPASS .EQ. 2) THEN        IF ((LPLOT .AND. .NOT. PLNOW) .OR.     1      (NPLT .EQ. 2 .AND. EPLOT(1) .AND. EPLOT(2)) .OR.      2      (NSTEPP .EQ. 1 .AND. NSTEPS .GT. 1)) THEN          DO 3810 J = 1, NPLT          JCON = JPLOT(J)          KCON = KPLOT(J)          CALL NAME10          HPLOT(J) = FTNAME 3810     CONTINUE          WRITE (NPLOT,9380) (HPLOT(J), J = 1, NPLT)        ENDIF        IF (PLNOW) CALL PLOTIT      ENDIF      GO TO 5000CC     41. -- ELECTROSTATIC SEPTUMC 4100 IF (.NOT. (PRON .AND. ELPR)) GO TO 5000      IF (TYPEC .EQ. 20) GO TO 4160C 4110 IF (SUPP) GO TO 4165      LOUT = L/UNITO(8)C 4130 IE = IPTOJ(4)      IF (IE .NE. 0) GO TO 4140      VNORM = VOLTS/UNITO(14)      APOUT = AP/UNITO(1)      WRITE (NOUT,9410) NUM, LABOUT, LOUT, XDIME(8), VNORM, XDIME(14),     1                  APOUT, XDIME(1)      GO TO 5000C 4140 ENORM = EFIELD*UNITO(1)/UNITO(14)      WRITE (NOUT,9411) NUM, LABOUT, LOUT, XDIME(8), ENORM, XDIME(14),     1                  XDIME(1)      GO TO 5000C 4160 THOUT = TH/UNITO(13)      WRITE (NOUT,9200) NUM, BLANK, THOUT, XDIME(13)      GO TO 5000C 4165 WRITE (NOUT,9050) NUM, LABOUT      GO TO 5000CC     42. -- KICKER -- CORRECTOR FOR BOTH PLANESC 4200 IF (.NOT. (PRON .AND. ELPR)) GO TO 5000      IF (TYPEC .EQ. 20) GO TO 4260      IF (SUPP) GO TO 4250      LOUT = LBEND/UNITO(8)      BNORM = B/UNITO(9)      ALNORM = AL/UNITO(7)      IF (L .EQ. 0.0 .AND. AL .NE. 0.0) GO TO 4210      WRITE (NOUT,9350) NUM, LABOUT, LOUT, XDIME(8), BNORM, XDIME(9),     1                  ALNORM, XDIME(7)      GO TO 5000C 4210 WRITE (NOUT,9351) NUM, LABOUT, LOUT, XDIME(8), ALNORM, XDIME(7)      GO TO 5000C 4250 WRITE (NOUT,9350) NUM, LABOUT      GO TO 5000C 4260 IF (SUPP) GO TO 4265      THOUT = TH/UNITO(13)      WRITE (NOUT,9200) NUM, BLANK, THOUT, XDIME(13)      GO TO 5000C 4265 WRITE (NOUT,9200) NUM, BLANK      GO TO 5000CC     43. -- REFERENCE COORDINATE SYSTEM SHIFTC 4300 NRT = .FALSE.      IF (.NOT. (PRON .AND. ELPR)) GO TO 5000      IF (.NOT. SUPP) THEN        DO 4310 J = 1, 6 4310   CODO(J) = COD(J)/UNITO(J)        WRITE (NOUT,9430) NUM, LABOUT, (CODO(J), XDIME(J), J = 1, 6)      ELSE        WRITE (NOUT,9430) NUM, LABOUT      ENDIF      GO TO 5000CC     45. -- NEUTRINO HORNC 4500 IF (PRON .AND. ELPR) THEN        IF (.NOT. SUPP) THEN          LOUT = L/UNITO(8)          WRITE (NOUT,9450) NUM, LABOUT, LOUT, XDIME(8)        ELSE          WRITE (NOUT,9450) NUM, LABOUT        ENDIF      ENDIF      GO TO 5000CC     46. -- HMONITORC 4600 IF (PRON .AND. ELPR) THEN        IF (.NOT. SUPP) THEN          LOUT = L/UNITO(8)          WRITE (NOUT,9460) NUM, LABOUT, LOUT, XDIME(8)        ELSE          WRITE (NOUT,9460) NUM, LABOUT        ENDIF      ENDIF      GO TO 5000CC     47. -- VMONITORC 4700 IF (PRON .AND. ELPR) THEN        IF (.NOT. SUPP) THEN          LOUT = L/UNITO(8)          WRITE (NOUT,9470) NUM, LABOUT, LOUT, XDIME(8)        ELSE          WRITE (NOUT,9470) NUM, LABOUT        ENDIF      ENDIF      GO TO 5000CC     48. -- MONITORC 4800 IF (PRON .AND. ELPR) THEN        IF (.NOT. SUPP) THEN          LOUT = L/UNITO(8)          WRITE (NOUT,9480) NUM, LABOUT, LOUT, XDIME(8)        ELSE          WRITE (NOUT,9480) NUM, LABOUT        ENDIF      ENDIF      GO TO 5000CC     RETURNC 5000 RETURNC 9010 FORMAT (2H (,I4,')',2X,'*BEAM*',9X,A8,F13.5,1X,A3,'/C') 9011 FORMAT (2H (,I4,')',2X,'*ADD TO BEAM*',2X,A8,F13.5,1X,A3,'/C') 9020 FORMAT (2H (,I4,')',2X,'*ROTAT*',8X,A8,3(F13.5,1X,A4),     1        '**-1') 9021 FORMAT (43X,'FORM FACTORS',3F13.5) 9030 FORMAT (2H (,I4,')',2X,'*DRIFT*',8X,A8,F13.5,1X,A4) 9040 FORMAT (2H (,I4,')',2X,'*',A5,'*',8X,A8,2(F13.5,1X,A4),     1        F13.5,5X,' (',F10.3,1X,A4,',',F10.5,1X,A4,')') 9041 FORMAT (2H (,I4,')',2X,'*',A5,'*',8X,A8,2(F13.5,1X,A4),     1        E13.5,1X,A4,'**-2',5X,' (',F10.3,1X,A4,',',     2        F10.5,1X,A4,')') 9042 FORMAT (2H (,I4,')',2X,'*',A5,'*',8X,A8,F13.5,1X,A4, F13.5,     1        5X,' (',F10.3,1X,A4,',',F10.5,1X,A4,')') 9043 FORMAT (2H (,I4,')',2X,'*',A5,'*',8X,A8,F13.5,1X,A4,E13.5,     1        1X,A4,'**-2',5X,' (',F10.3,1X,A4,1H,,F10.5,1X,A4,1H)) 9044 FORMAT (2H (,I4,')',2X,'*',A5,'*',8X,A8,2(F13.5,1X,A4),     1        F13.5,5X,' (',7X,'BIG',5X,',',F10.5,1X,A4,')') 9050 FORMAT (2H (,I4,')',2X,'*QUAD*',9X,A8,3(F13.5,1X,A4),' (',     1        A11,1X,A4,')') 9051 FORMAT (2H (,I4,')',2X,'*QUAD*',9X,A8,F13.5,1X,A4,F13.5,1X,     1        A4,1H/,A4,13X,2H (,A11,1X,A4,1H)) 9052 FORMAT (2H (,I4,')',2X,'*QUAD*',9X,A8,F13.5,1X,A4,F13.5,1X,     1        A4,4H**-2,14X,2H (,A11,1X,A4,1H)) 9053 FORMAT (F11.5) 9054 FORMAT (E11.5) 9060 FORMAT (2H (,I4,')',2X,'*UPDATE*',7X,A8,5X,A4) 9061 FORMAT (2H (,I4,')',2X,'*SLIT*',9X,A8,I8,'.',F13.5,1X,A4) 9062 FORMAT (2H (,I4,')',2X,'*ENTER ALIGN*',2X,A8) 9070 FORMAT (2H (,I4,')',2X,'*CENT SHIFT*',3X,A8/7X,     1        6(F13.5,1X,A4)) 9080 FORMAT (2H (,I4,')',2X,'*ALIGN*',8X,A8/7X,     1        6(F12.5,1X,A4),4X,A20) 9081 FORMAT (2H (,I4,')',2X,'*EXIT ALIGN*',3X,A8/7X,     1        6(F12.5,1X,A4),4X,A20) 9100 FORMAT (2H (,I4,')',2X,A10,5X,A8,5X,A8,     1        A14,2H /,A7,8X,'(',A12,' )') 9101 FORMAT (' (',I4,')',2X,A10,5X,A8,5X,A8,     1        A14,' /',A7,8X,'( (PI/2.0)*ACOS(',A9,') )') 9102 FORMAT (2H (,I4,')',2X,A10,5X,A8,5X,A8,     1        A14,2H /,A7,/,46X,'(',A12,' )')    9103 FORMAT (' (',I4,')',2X,A10,5X,A8,5X,A8,     1        A14,' /',A7,/,46X,'( (PI/2.0)*ACOS(',A9,') )') 9104 FORMAT (F12.5) 9105 FORMAT (E12.3) 9106 FORMAT (F9.5) 9107 FORMAT (F14.5) 9108 FORMAT (E14.5) 9109 FORMAT (F7.5) 9110 FORMAT (2H (,I4,')',2X,'*ACCEL*',8X,A8,F13.5,1X,A4,     1        F13.5,5X,'(',F11.5,2H) ,A4,F13.5,F18.5) 9111 FORMAT (E7.2) 9112 FORMAT (2H (,I4,')',2X,A10,5X,A8,5X,A8,     1        A14,2H /,A7,/,46X,'(',A12,1X,'+-',1X,A12,' )')    9113 FORMAT (2H (,I4,')',2X,A10,5X,A8,5X,A8,     1        A14,2H /,A7,8X,'(',A12,1X,'+-',1x,A12,' )') 9120 FORMAT (2H (,I4,')',2X,'*CORRELATIONS*',1X,A8) 9130 FORMAT (2H (,I4,')',2X,'*REALIGN*',6X,A8) 9131 FORMAT (2H (,I4,')',2X,'*LEVEL COORDS*',2X,A8) 9140 FORMAT (2H (,I4,')',2X,'*MATRIX*',7X,A8,'    ROW',I4,'.') 9141 FORMAT (2H (,I4,')',2X,'*MATRIX*',7X,A8,'    ROW',I4,'.',     1        ' + 2ND ORDER TERMS') 9142 FORMAT (2H (,I4,')',2X,'*MATRIX*',7X,A8,'    ROW',I4,'.',     1        ' + 2ND AND 3RD ORDER TERMS') 9160 FORMAT (2H (,I4,')',2X,1H*,A6,1H*,7X,A8,4X,E13.5) 9161 FORMAT (2H (,I4,')',2X,1H*,A6,1H*,7X,A8,3X,A16) 9162 FORMAT (4I4) 9170 FORMAT (2H (,I4,')',2X,'*1ST ORDER*',4X,A8,31X,     1        I5,'.',I5,1H.) 9171 FORMAT (2H (,I4,')',2X,'*2ND ORDER*',4X,A8,10X,     1        'GAUSSIAN DISTRIBUTION',I5,'.',I5,1H.) 9172 FORMAT (2H (,I4,')',2X,'*3RD ORDER*',4X,A8,10X,     1        'GAUSSIAN DISTRIBUTION',I5,'.',I5,1H.) 9180 FORMAT (2H (,I4,')',2X,'*SEXT*',9X,A8,3(F13.5,1X,A4)) 9181 FORMAT (2H (,I4,')',2X,'*SEXT*',9X,A8,F13.5,1X,A4,     1        F13.5,1X,A4,'**-3') 9190 FORMAT (2H (,I4,')',2X,'*SOLE*',9X,A8,2(F13.5,1X,A4),     1        2H (,F11.5,1X,A4,1H,,F13.5,1X,A4,1H)) 9191 FORMAT (2H (,I4,')',2X,'*SOLE*',9X,A8,F13.5,1X,A4,     1        F13.5,' DEG') 9200 FORMAT (2H (,I4,')',2X,'*SROT*',9X,A8,F13.5,1X,A4) 9210 FORMAT (2H (,I4,')',2X,'*E21*',10X,A8,F13.0,2F18.5) 9250 FORMAT (2H (,I4,')',2X,'*OCT*',10X,A8,3(F13.5,1X,A4)) 9251 FORMAT (2H (,I4,')',2X,'*OCT*',10X,A8,F13.5,1X,A4,     1        E13.5,1X,A4,'**-4') 9270 FORMAT (2H (,I4,')',2X,'*ETA*',10X,A8/7X,     1        6(F12.5,1X,A4)) 9271 FORMAT (2H (,I4,')',2X,'*RAY*',11X,A8/7X,     1        6(F12.5,1X,A4)) 9281 FORMAT (2H (,I4,')',2X,'*     *',8X,A8,3(F13.5,1X,A4),     1        '**-1') 9300 FORMAT (2H (,I4,')',2X,'*PARAM*',8X,A8,4X,E16.8) 9310 FORMAT (2H (,I4,')',2X,'*MARKER*',7X,A8) 9330 FORMAT (2H (,I4,')',2X,'*STORE*',8X,A8,4X,E13.5) 9340 FORMAT (2H (,I4,')',2X,'*PLASMA LENS*',2X,A8,3(F13.5,1X,A4)     1        ,2H (,F11.5,1X,A4,1H)) 9341 FORMAT (2H (,I4,')',2X,'*PLASMA LENS*',2X,A8,F13.5,1X,A4,     1        F13.5,1X,A4,1H/,A4,13X,2H (,F11.5,1X,A4,1H)) 9342 FORMAT (2H (,I4,')',2X,'*PLASMA LENS*',2X,A8,F13.5,1X,A4,     1        F13.5,1X,A4,4H**-2,14X,2H (,F11.5,1X,A4,1H)) 9343 FORMAT (2H (,I4,')',2X,'*PLASMA LENS*',2X,A8,F13.5,1X,A4,     1        E13.5,1X,A4,4H**-2,14X,2H (,F11.5,1X,A4,1H)) 9350 FORMAT (2H (,I4,')',2X,'*HKICK*',8X,A8,2(F13.5,1X,A4),     1        2H (,F11.5,1X,A4,1H)) 9351 FORMAT (2H (,I4,')',2X,'*HKICK*',8X,A8,F13.5,1X,A4,18X,     1        2H (,F11.5,1X,A4,1H)) 9360 FORMAT (2H (,I4,')',2X,'*VKICK*',8X,A8,2(F13.5,1X,A4),     1        2H (,F11.5,1X,A4,1H)) 9361 FORMAT (2H (,I4,')',2X,'*VKICK*',8X,A8,F13.5,1X,A4,18X,     1        2H (,F11.5,1X,A4,1H)) 9370 FORMAT (2H (,I4,')',2X,'*ALMARK*',7X,A8,5X,A4) 9372 FORMAT (2H (,I4,')',2X,'*ENTER ALIGN*',2X,A8) 9380 FORMAT (8A10) 9410 FORMAT (2H (,I4,')',2X,'*SEPTUM*',7X,A8,3(F13.5,1X,A4)) 9411 FORMAT (2H (,I4,')',2X,'*SEPTUM*',7X,A8,F13.5,1X,A4,F13.5,1X,     1        A4,1H/,A4) 9430 FORMAT (2H (,I4,')',2X,'*SHIFT*',8X,A8/7X,     1        6(F13.5,1X,A4)) 9450 FORMAT (2H (,I4,')',2X,'*NEUTRINO HORN*',A8,F13.5,1X,A4) 9460 FORMAT (2H (,I4,')',2X,'*HMONITOR*',5X,A8,F13.5,1X,A4) 9470 FORMAT (2H (,I4,')',2X,'*VMONITOR*',5X,A8,F13.5,1X,A4) 9480 FORMAT (2H (,I4,')',2X,'*MONITOR*',6X,A8,F13.5,1X,A4)      END